import React from "react";

const Pagination = ({ filter, setFilter, totalCount }) => {
    const totalPages = Math.max(1, Math.ceil(totalCount / filter.limit)); // Oprava: minimálně 1 stránka

    const changePage = (newPage) => {
        if (newPage >= 0 && newPage < totalPages) {
            setFilter((prev) => ({ ...prev, page: newPage }));
        }
    };

    return (
        <nav aria-label="Navigace stránek" className="mt-3">
            <ul className="pagination justify-content-center">
                <li className={`page-item ${filter.page === 0 ? "disabled" : ""}`}>
                    <button className="page-link custom-page-link" onClick={() => changePage(filter.page - 1)}>
                        ⬅ Předchozí
                    </button>
                </li>

                <li className="page-item active">
                    <span className="page-link custom-page-info">
                        Strana {filter.page + 1} z {totalPages}
                    </span>
                </li>

                <li className={`page-item ${filter.page >= totalPages - 1 ? "disabled" : ""}`}>
                    <button className="page-link custom-page-link" onClick={() => changePage(filter.page + 1)}>
                        Další ➡
                    </button>
                </li>
            </ul>
        </nav>
    );
};

export default Pagination;
